import type { BankQuestion } from "@/lib/bank";

/** Animal Kingdom and Structural Organisation in Animals (Biology (NEET)): 134 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-animal-kingdom-1","question":"Animals with jointed appendages, an exoskeleton of chitin and the largest number of species belong to the phylum:","options":["Echinodermata","Mollusca","Arthropoda","Annelida"],"answer":2,"explanation":"Arthropoda (arthros = joint, poda = appendages) is the largest phylum; about two-thirds of all named species on Earth are arthropods.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-2","question":"Comb plates, eight external rows of ciliated plates that help in locomotion, are characteristic of:","options":["Cnidaria","Ctenophora","Porifera","Platyhelminthes"],"answer":1,"explanation":"Ctenophores (sea walnuts or comb jellies, e.g., Pleurobrachia, Ctenoplana) swim with comb plates; bioluminescence is well marked in them.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-3","question":"Dense regular connective tissue that attaches one bone to another bone is called a:","options":["Cartilage","Ligament","Tendon","Adipose tissue"],"answer":1,"explanation":"Ligaments attach bone to bone, whereas tendons attach skeletal muscles to bones; both are dense regular connective tissue.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-4","question":"Specialised flame cells that help in osmoregulation and excretion are found in:","options":["Ctenophora","Annelida","Platyhelminthes","Aschelminthes"],"answer":2,"explanation":"Flatworms such as Taenia and Fasciola have flame cells. Annelids have nephridia, and in aschelminths an excretory tube removes body wastes through the excretory pore.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-5","question":"A water vascular system that helps in locomotion, capture and transport of food and respiration is characteristic of:","options":["Hemichordata","Echinodermata","Porifera","Mollusca"],"answer":1,"explanation":"The water vascular system is a distinctive feature of echinoderms (starfish, sea urchin, sea cucumber). Sponges have a water transport or canal system, which is a different thing.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-6","question":"Alternation of generation between the asexual polyp and the sexual medusa (metagenesis) is shown by:","options":["Aurelia","Obelia","Hydra","Adamsia"],"answer":1,"explanation":"Cnidarians with both forms show metagenesis, e.g., Obelia, where polyps produce medusae asexually and medusae form polyps sexually. Hydra and Adamsia exist only as polyps, and Aurelia is a medusa.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-7","question":"Which of the following is NOT a mammal?","options":["Ornithorhynchus","Hippocampus","Pteropus","Macropus"],"answer":1,"explanation":"Hippocampus (sea horse) is a bony fish. Ornithorhynchus (platypus, oviparous), Macropus (kangaroo) and Pteropus (flying fox) are mammals.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-8","question":"The inner surface of hollow organs such as the bronchioles and fallopian tubes is lined by:","options":["Compound epithelium","Ciliated epithelium","Keratinised stratified epithelium","Squamous epithelium"],"answer":1,"explanation":"Columnar or cuboidal cells bearing cilia line the bronchioles and fallopian tubes; the cilia move particles or mucus in a specific direction.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-9","question":"In which phylum is the body cavity not lined by mesoderm, the mesoderm being present as scattered pouches between the ectoderm and endoderm?","options":["Aschelminthes","Platyhelminthes","Annelida","Arthropoda"],"answer":0,"explanation":"Such a body cavity is a pseudocoelom, found in aschelminths (roundworms). Platyhelminthes are acoelomate, and annelids and arthropods are true coelomates.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-10","question":"In Urochordata (e.g., Ascidia, Salpa, Doliolum), the notochord is present:","options":["Throughout life from head to tail","Only in the adult head region","Never at any stage","Only in the larval tail"],"answer":3,"explanation":"In urochordates the notochord is present only in the larval tail. In cephalochordates such as Branchiostoma it extends from head to tail and persists throughout life.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-11","question":"Which statement about Chondrichthyes is INCORRECT?","options":["The notochord is persistent throughout life","In males, pelvic fins bear claspers","Gill slits are separate and without an operculum","They have an air bladder that prevents sinking"],"answer":3,"explanation":"Cartilaginous fishes lack an air bladder, so they have to swim constantly to avoid sinking. The air bladder is a feature of bony fishes (Osteichthyes).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-12","question":"Which group contains only homeothermous (warm-blooded) animals?","options":["Corvus, Columba, Delphinus","Testudo, Psittacula, Felis","Hyla, Corvus, Pteropus","Chelone, Columba, Canis"],"answer":0,"explanation":"Birds (Corvus, Columba) and mammals (Delphinus) are homeothermous. Hyla is an amphibian and Chelone and Testudo are reptiles, all poikilothermous.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-13","question":"Air sacs connected to the lungs supplement respiration in:","options":["Birds","Reptiles","Amphibians","Bony fishes"],"answer":0,"explanation":"In birds (Aves) the lungs are connected to air sacs that supplement respiration; birds also have pneumatic bones, a crop and a gizzard.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-14","question":"Which statement about sponges (Porifera) is INCORRECT?","options":["Fertilisation is external and development is direct","Sexes are not separate (hermaphrodite)","The body is supported by spicules or spongin fibres","Choanocytes or collar cells line the spongocoel and the canals"],"answer":0,"explanation":"In sponges fertilisation is internal and development is indirect, with a larval stage morphologically distinct from the adult. The other three statements are correct.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-15","question":"Which cell junctions allow neighbouring cells to communicate by connecting their cytoplasm, permitting rapid transfer of ions, small molecules and sometimes big molecules?","options":["Desmosome-free junctions","Gap junctions","Tight junctions","Adhering junctions"],"answer":1,"explanation":"Gap junctions connect the cytoplasm of adjoining cells. Tight junctions stop substances from leaking across a tissue, and adhering junctions cement neighbouring cells together.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-16","question":"In a male frog, the ureters:","options":["Open into the urinary bladder, which opens outside through a urethra","Act as urinogenital ducts that open into the cloaca","Open separately from the vasa efferentia directly to the exterior","Are absent, and the kidneys open directly into the cloaca"],"answer":1,"explanation":"In male frogs the ureters carry both urine and sperm (urinogenital ducts) and open into the cloaca. In females the ureters and oviducts open separately into the cloaca.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-17","question":"Which pair of animals has an open circulatory system?","options":["Nereis and Pila","Pheretima and Periplaneta","Pila and Periplaneta","Ascaris and Pheretima"],"answer":2,"explanation":"Arthropods (Periplaneta) and molluscs (Pila) have an open circulatory system. Annelids such as Pheretima and Nereis have a closed system.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-18","question":"Tendons and ligaments are examples of:","options":["Dense irregular connective tissue","Loose areolar connective tissue","Dense regular connective tissue","Specialised cartilage"],"answer":2,"explanation":"In dense regular tissue the collagen fibres lie in rows between many parallel bundles of fibres, as in tendons and ligaments. Dense irregular tissue, with fibres in all directions, is found in the skin.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-19","question":"How many of the following statements about chordates are correct?\n(i) Chordates possess a notochord, a dorsal hollow single nerve cord and paired pharyngeal gill slits.\n(ii) In chordates the heart is ventral.\n(iii) A post-anal tail is present in chordates.\n(iv) Hemichordates are now placed as a sub-phylum of phylum Chordata.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Hemichordata was earlier treated as a sub-phylum of Chordata but is now placed as a separate phylum under non-chordates.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-20","question":"Match the animal with its phylum.\nList I: (A) Antedon (B) Pinctada (C) Ancylostoma (D) Saccoglossus\nList II: (1) Mollusca (2) Echinodermata (3) Aschelminthes (4) Hemichordata","options":["A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-4, B-1, C-3, D-2","A-1, B-2, C-3, D-4"],"answer":0,"explanation":"Antedon is the sea lily (echinoderm), Pinctada the pearl oyster (mollusc), Ancylostoma the hookworm (aschelminth) and Saccoglossus a hemichordate.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-21","question":"Assertion (A): Adult echinoderms are radially symmetrical.\nReason (R): Echinoderm larvae are bilaterally symmetrical.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but the bilateral symmetry of the larva does not explain the radial symmetry of the adult; it actually shows that echinoderms evolved from bilateral ancestors.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-22","question":"How many of the following statements about class Mammalia are correct?\n(i) The most unique feature is the presence of milk-producing mammary glands.\n(ii) Mammals are poikilothermous.\n(iii) All mammals are viviparous.\n(iv) External ears or pinnae are present.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iv) are correct. Mammals are homeothermous, and although most are viviparous, a few such as Ornithorhynchus (platypus) are oviparous.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-23","question":"All of the following are features of cyclostomes EXCEPT:","options":["A sucking and circular mouth without jaws","6–15 pairs of gill slits for respiration","A cartilaginous cranium and vertebral column","Body bears scales and paired fins"],"answer":3,"explanation":"Cyclostomes (Petromyzon, Myxine) have a body devoid of scales and paired fins. They are marine but migrate to fresh water for spawning and die a few days after spawning.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-24","question":"How many of the following statements about fishes are correct?\n(i) Bony fishes have four pairs of gills covered by an operculum on each side.\n(ii) An air bladder that regulates buoyancy is present in bony fishes.\n(iii) Teeth of cartilaginous fishes are modified placoid scales that are backwardly directed.\n(iv) Torpedo has electric organs, while Trygon has a poison sting.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Torpedo (electric ray) and Trygon (sting ray) are cartilaginous fishes; Exocoetus, Hippocampus and Labeo are bony fishes.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-25","question":"Match the epithelium with its location.\nList I: (A) Squamous epithelium (B) Cuboidal epithelium (C) Columnar epithelium (D) Compound epithelium\nList II: (1) Lining of stomach and intestine (2) Walls of blood vessels and air sacs of lungs (3) Inner lining of ducts of salivary glands and pancreatic ducts (4) Ducts of glands and tubular parts of nephrons","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":2,"explanation":"Squamous (flat) cells form diffusion boundaries such as blood vessel walls and alveoli; cuboidal cells line gland ducts and nephron tubules; columnar cells line the stomach and intestine; multilayered compound epithelium protects the inner lining of salivary and pancreatic ducts.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-26","question":"How many of the following statements about muscle and neural tissue are correct?\n(i) Skeletal muscle fibres are striated and bundled together in a parallel fashion.\n(ii) Smooth muscles are voluntary and are found in the biceps.\n(iii) Intercalated discs in cardiac muscle allow the cells to contract as a unit.\n(iv) Neurons make up more than one-half the volume of neural tissue in our body.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(i) and (iii) are correct. (ii) is wrong: smooth muscles are involuntary and found in visceral walls; the biceps is skeletal muscle. (iv) is wrong: it is the neuroglial cells, not neurons, that make up more than one-half the volume of neural tissue.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-27","question":"How many of the following statements about the frog are correct?\n(i) The skin acts as a respiratory organ when the frog is in water.\n(ii) The heart has two atria and one ventricle.\n(iii) Frogs are ammonotelic.\n(iv) Fertilisation is internal.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (ii) are correct. The frog is ureotelic and fertilisation is external, with development through a tadpole larva.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-28","question":"Which combination of organism and features is CORRECT?","options":["Pleurobrachia: diploblastic, cnidoblasts present, shows metagenesis","Ascaris: pseudocoelomate, sexes separate, females longer than males","Fasciola: coelomate, dioecious, excretion by nephridia","Pheretima: open circulatory system, true metamerism, nephridia"],"answer":1,"explanation":"Ascaris is a pseudocoelomate with separate sexes and sexual dimorphism. Fasciola is an acoelomate hermaphrodite with flame cells, Pheretima has a closed circulation, and ctenophores like Pleurobrachia lack cnidoblasts and metagenesis.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-29","question":"Match the animal group with its level of organisation.\nList I: (A) Sponges (B) Coelenterates (C) Platyhelminthes (D) Annelids\nList II: (1) Organ level (2) Cellular level (3) Organ system level (4) Tissue level","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"Sponges are aggregates of cells (cellular level); coelenterates show tissue level; platyhelminthes show organ level; annelids, arthropods, molluscs, echinoderms and chordates show organ-system level.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-30","question":"Assertion (A): Crocodiles have a four-chambered heart.\nReason (R): All reptiles have a completely divided ventricle.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: most reptiles have a three-chambered heart with an incompletely divided ventricle; only crocodiles have four chambers.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-animal-kingdom-31", "question": "Cnidoblasts (cnidocytes), stinging cells used for anchorage, defence and capture of prey, are characteristic of:", "options": ["Cnidaria", "Porifera", "Ctenophora", "Platyhelminthes"], "answer": 0, "explanation": "Cnidarians get their name from cnidoblasts, present on the tentacles and body. Ctenophores lack them and have comb plates instead.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-32", "question": "Areolar tissue, present beneath the skin, is an example of:", "options": ["Dense regular connective tissue", "Loose connective tissue", "Specialised connective tissue", "Compound epithelium"], "answer": 1, "explanation": "Areolar tissue and adipose tissue are loose connective tissues; their cells and fibres are loosely arranged in a semi-fluid ground substance.", "difficulty": "easy", "source": "NEET pattern"},
  {"id":"bio-animal-kingdom-33","question":"Pheretima (earthworm) and Hirudinaria (blood-sucking leech) belong to the phylum:","options":["Mollusca","Aschelminthes","Annelida","Platyhelminthes"],"answer":2,"explanation":"Pheretima and Hirudinaria are both metamerically segmented, triploblastic coelomates with nephridia, the hallmarks of Annelida. Aschelminthes (roundworms) look worm-like too but are unsegmented pseudocoelomates, which is the trap.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-animal-kingdom-34", "question": "Nephridia, which help in osmoregulation and excretion, are found in:", "options": ["Arthropods", "Molluscs", "Echinoderms", "Annelids"], "answer": 3, "explanation": "Annelids such as Nereis, Pheretima and Hirudinaria excrete through nephridia. Insects use Malpighian tubules, and flatworms use flame cells.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-35", "question": "The radula, a file-like rasping organ used for feeding, is present in the mouth of:", "options": ["Molluscs", "Echinoderms", "Annelids", "Hemichordates"], "answer": 0, "explanation": "The molluscan mouth contains the radula; molluscs also have a mantle and feathery gills in the mantle cavity.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-animal-kingdom-36","question":"Bioluminescence, the property of a living organism to emit light, is well marked in:","options":["Sponges such as Sycon","Ctenophores (comb jellies)","Flatworms such as Taenia","Roundworms such as Ascaris"],"answer":1,"explanation":"Ctenophores such as Pleurobrachia and Ctenoplana (sea walnuts, comb jellies) show well-marked bioluminescence, which NCERT singles out for this phylum. Sponges, flatworms and roundworms are not noted for it.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-37","question":"In insects such as the cockroach, excretion takes place through:","options":["Segmental nephridia","Flame cells","Malpighian tubules","Green glands only"],"answer":2,"explanation":"Arthropods, including insects, excrete mainly through Malpighian tubules. Nephridia are annelid excretory organs, and flame cells are found in flatworms.","difficulty":"moderate","source":"NEET pattern"},
  {"id": "bio-animal-kingdom-38", "question": "Excess nutrients that are not used immediately are converted into fat and stored in:", "options": ["Areolar tissue", "Dense irregular connective tissue", "Cartilage", "Adipose tissue"], "answer": 3, "explanation": "Adipose tissue is loose connective tissue located mainly beneath the skin; its cells are specialised to store fat.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-39", "question": "The worm-like body of Balanoglossus is divided into:", "options": ["Proboscis, collar and trunk", "Head, thorax and abdomen", "Scolex, neck and proglottids", "Prostomium, peristomium and pygidium"], "answer": 0, "explanation": "Hemichordates such as Balanoglossus and Saccoglossus have a body made of an anterior proboscis, a collar and a long trunk.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-40", "question": "Which connective tissue has a solid, pliable matrix that resists compression, with its cells enclosed in small cavities, and is found in the tip of the nose and the outer ear?", "options": ["Bone", "Cartilage", "Dense regular tissue", "Adipose tissue"], "answer": 1, "explanation": "Cartilage has a pliable matrix with chondrocytes in cavities; it is found in the tip of the nose, outer ear joints and between adjacent vertebrae. Bone matrix is hard and non-pliable.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-animal-kingdom-41","question":"Which of the following is NOT a specialised connective tissue?","options":["Hyaline cartilage","Bone","Adipose tissue","Blood"],"answer":2,"explanation":"Cartilage, bone and blood are the specialised connective tissues. Adipose tissue is a loose connective tissue.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-42","question":"Metameric segmentation, in which the body is divided externally and internally into segments with serial repetition of at least some organs, is shown by:","options":["Taenia","Ascaris","Ancylostoma","Pheretima"],"answer":3,"explanation":"The earthworm shows true metamerism. The proglottids of Taenia are not true segments, and the roundworms Ascaris and Ancylostoma are unsegmented pseudocoelomates.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-43","question":"Which statement about ctenophores is correct?","options":["Only sexual reproduction, external fertilisation, indirect development","Sexes are separate, and development is direct without any larva","They reproduce both asexually and sexually, with internal fertilisation","They show metagenesis like Obelia, with polyp and medusa stages"],"answer":0,"explanation":"Ctenophores are hermaphrodite, reproduce only sexually, and have external fertilisation with indirect development.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-animal-kingdom-44", "question": "The crop and the gizzard, additional chambers of the digestive tract, are characteristic of:", "options": ["Reptiles", "Birds", "Mammals", "Cartilaginous fishes"], "answer": 1, "explanation": "The digestive tract of birds has a crop for storing food and a muscular gizzard for grinding it.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-45", "question": "Which of the following is a poisonous snake?", "options": ["Hemidactylus", "Calotes", "Bangarus", "Chelone"], "answer": 2, "explanation": "Bangarus (krait), Naja (cobra) and Vipera (viper) are poisonous snakes. Hemidactylus is the wall lizard, Calotes the garden lizard, and Chelone a turtle.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-46", "question": "Which of the following is a limbless amphibian?", "options": ["Hyla", "Salamandra", "Bufo", "Ichthyophis"], "answer": 3, "explanation": "Ichthyophis is a limbless amphibian. Hyla is the tree frog, Salamandra the salamander, and Bufo the toad, all with limbs.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-47", "question": "Which type of animal tissue is the most abundant and widely distributed in the body of complex animals?", "options": ["Connective tissue", "Epithelial tissue", "Muscular tissue", "Neural tissue"], "answer": 0, "explanation": "Connective tissues, ranging from soft tissues to bone, cartilage and blood, link and support the other tissues and are the most abundant and widely distributed.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-animal-kingdom-48","question":"A male frog can be distinguished from a female frog by the presence of:","options":["A cloaca at the posterior end","Vocal sacs and copulatory pads","Moist skin with mucous glands","Webbed digits on the hind limbs"],"answer":1,"explanation":"Frogs show sexual dimorphism: males have vocal sacs and copulatory pads. Both sexes have a cloaca, a tympanum and webbed hind limbs.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-animal-kingdom-49", "question": "How many of the following statements about phylum Arthropoda are correct?\n(i) The body consists of head, thorax and abdomen.\n(ii) Respiratory organs are gills, book gills, book lungs or a tracheal system.\n(iii) The circulatory system is of the closed type.\n(iv) Limulus, the living fossil, is an arthropod.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are correct. Arthropods have an open circulatory system, so (iii) is wrong; Limulus (king crab) is the living fossil.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-50", "question": "Match the mollusc with its common name.\nList I: (A) Octopus (B) Sepia (C) Dentalium (D) Aplysia\nList II: (1) Tusk shell (2) Sea hare (3) Cuttlefish (4) Devil fish", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-4, B-1, C-3, D-2"], "answer": 2, "explanation": "Octopus is the devil fish, Sepia the cuttlefish, Dentalium the tusk shell, and Aplysia the sea hare; Loligo is the squid and Pinctada the pearl oyster.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-51", "question": "Assertion (A): Cyclostomes such as Petromyzon migrate to fresh water for spawning.\nReason (R): Cyclostomes die within a few days after spawning, and their larvae return to the ocean after metamorphosis.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both statements are true, but dying after spawning does not explain why they migrate to fresh water to spawn; R only describes what follows spawning.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-52", "question": "How many of the following statements about cell junctions and epithelia are correct?\n(i) Tight junctions help to stop substances from leaking across a tissue.\n(ii) Adhering junctions perform cementing to keep neighbouring cells together.\n(iii) Gap junctions connect the cytoplasm of adjoining cells.\n(iv) Compound epithelium has a major role in secretion and absorption.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct. Compound epithelium has only a limited role in secretion and absorption; its main function is protection against chemical and mechanical stresses.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-53", "question": "Match the cartilaginous fish with its common name.\nList I: (A) Torpedo (B) Pristis (C) Carcharodon (D) Trygon\nList II: (1) Saw fish (2) Sting ray (3) Electric ray (4) Great white shark", "options": ["A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-3, B-4, C-1, D-2", "A-3, B-1, C-4, D-2"], "answer": 3, "explanation": "Torpedo is the electric ray (it has electric organs), Pristis the saw fish, Carcharodon the great white shark, and Trygon the sting ray (it has a poison sting).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-54", "question": "All of the following are bony fishes (Osteichthyes) EXCEPT:", "options": ["Scoliodon", "Exocoetus", "Labeo", "Betta"], "answer": 0, "explanation": "Scoliodon (dog fish) is a cartilaginous fish. Exocoetus (flying fish), Labeo (rohu) and Betta (fighting fish) are bony fishes.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-55", "question": "How many of the following statements about the frog are correct?\n(i) Frogs are ureotelic, excreting urea.\n(ii) The frog has ten pairs of cranial nerves.\n(iii) Both a hepatic portal system and a renal portal system are present.\n(iv) An external ear is absent; only the tympanum can be seen externally.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The frog excretes urea, has 10 pairs of cranial nerves, has hepatic and renal portal systems, and has no external ear, only a tympanum that receives sound.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-56", "question": "Match the phylum with a feature characteristic of it.\nList I: (A) Aschelminthes (B) Mollusca (C) Arthropoda (D) Echinodermata\nList II: (1) Endoskeleton of calcareous ossicles (2) Muscular pharynx; females often longer than males (3) Mantle covering the visceral hump, with feathery gills in the mantle cavity (4) Compound eyes and statocysts", "options": ["A-2, B-4, C-3, D-1", "A-2, B-3, C-4, D-1", "A-3, B-2, C-4, D-1", "A-2, B-3, C-1, D-4"], "answer": 1, "explanation": "Roundworms have a muscular pharynx and are dioecious, females often longer than males. Molluscs have a mantle and gills, arthropods have compound eyes and statocysts, and echinoderms an endoskeleton of calcareous ossicles.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-57", "question": "Assertion (A): Bones are hard and non-pliable and form the main framework that supports the body.\nReason (R): The ground substance of bone is rich in calcium salts and collagen fibres, which give bone its strength.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The calcium salts and collagen fibres in the bone matrix are exactly what make bone hard, non-pliable and strong enough to support the body.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-58", "question": "Which combination of animal, phylum and feature is CORRECT?", "options": ["Aurelia – Ctenophora – comb plates", "Fasciola – Aschelminthes – pseudocoelom", "Nereis – Annelida – parapodia", "Asterias – Mollusca – water vascular system"], "answer": 2, "explanation": "Nereis, a marine annelid, swims with lateral appendages called parapodia. Aurelia is a cnidarian, Fasciola is an acoelomate flatworm, and Asterias is an echinoderm.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-59", "question": "How many of the following statements are correct?\n(i) Coelenterates show the tissue level of organisation.\n(ii) Annelids have an incomplete digestive system with a single opening.\n(iii) Platyhelminthes have an incomplete digestive system with a single opening.\n(iv) Ctenophores are triploblastic.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (iii) are correct. Annelids have a complete digestive tract with mouth and anus, and ctenophores, like cnidarians, are diploblastic.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-animal-kingdom-60", "question": "From the following list, how many animals are cold-blooded (poikilothermous)?\nPterophyllum, Hyla, Chameleon, Pavo, Macropus, Naja", "options": ["Two", "Three", "Four", "Five"], "answer": 2, "explanation": "Pterophyllum (angel fish), Hyla (tree frog), Chameleon and Naja (cobra) are poikilothermous, so four. Pavo (peacock) and Macropus (kangaroo) are homeothermous.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-animal-kingdom-61","question":"Which of the following is a flightless bird?","options":["Corvus","Columba","Psittacula","Struthio"],"answer":3,"explanation":"Struthio (ostrich) is a flightless bird. Corvus (crow), Columba (pigeon) and Psittacula (parrot) can all fly.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-62","question":"Long bones that are hollow with air cavities (pneumatic bones) are characteristic of:","options":["Reptilia","Aves","Mammalia","Amphibia"],"answer":1,"explanation":"In birds the endoskeleton is fully ossified and the long bones are hollow with air cavities, which lightens the body for flight. Reptile and mammal long bones are not pneumatic in this way.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-63","question":"Which of the following mammals lays eggs?","options":["Ornithorhynchus","Macropus","Balaenoptera","Panthera tigris"],"answer":0,"explanation":"Ornithorhynchus (platypus) is an oviparous mammal. Macropus (kangaroo) is a pouched mammal but still viviparous, which is the trap; Balaenoptera (blue whale) and Panthera tigris (tiger) are viviparous too.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-64","question":"In which of the following groups is there no external ear opening, the tympanum representing the ear?","options":["Mammals only","Birds and mammals","Amphibians and reptiles","Bony fishes and amphibians"],"answer":2,"explanation":"In both amphibians and reptiles the tympanum represents the ear and there is no external ear opening. Mammals have external ears (pinnae), and fishes have no tympanum.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-65","question":"Parapodia, lateral appendages that help in swimming, are found in:","options":["Pheretima","Hirudinaria","Nereis","Ascaris"],"answer":2,"explanation":"The aquatic annelid Nereis swims with parapodia. Pheretima (earthworm) and Hirudinaria (leech) lack them, and Ascaris is an aschelminth, not an annelid.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-66","question":"The teeth of a shark such as Carcharodon are:","options":["Modified cycloid scales","Modified placoid scales, directed backwards","Bony teeth fused to the jaw with no relation to scales","Modified ctenoid scales"],"answer":1,"explanation":"In cartilaginous fishes the teeth are modified placoid scales that point backwards; the skin also bears minute placoid scales. Cycloid and ctenoid scales belong to bony fishes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-67","question":"The excretory organ of hemichordates such as Balanoglossus is the:","options":["Flame cell","Nephridium","Malpighian tubule","Proboscis gland"],"answer":3,"explanation":"Hemichordates excrete through a proboscis gland. Flame cells are found in flatworms, nephridia in annelids and Malpighian tubules in most arthropods.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-68","question":"Which component makes up more than one-half of the volume of neural tissue in the body?","options":["Neuroglia","Neurons","Areolar tissue","Blood capillaries"],"answer":0,"explanation":"Neuroglial cells, which protect and support the neurons, make up more than half the volume of neural tissue. The neuron is the functional unit, but neurons are not the larger part by volume.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-69","question":"Communication junctions (intercalated discs) at fusion points that allow the cells to contract as a unit are characteristic of:","options":["Skeletal muscle","Smooth muscle","Cardiac muscle","Dense regular connective tissue"],"answer":2,"explanation":"In cardiac muscle, cell junctions fuse the plasma membranes of the cells, and intercalated discs let the cells contract as a unit. Skeletal muscle fibres are bundled in parallel without such discs.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-70","question":"Cuboidal epithelium bearing microvilli (a brush border) lines the:","options":["Air sacs (alveoli) of the lungs","Proximal convoluted tubule of the nephron","Inner lining of blood vessels and the heart","Dry, keratinised surface of the skin"],"answer":1,"explanation":"The cuboidal cells of the proximal convoluted tubule carry microvilli. Air sacs and blood vessel walls have squamous epithelium, and the skin surface has compound epithelium.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-71","question":"Match the bony fish with its common name.\nList I: (A) Exocoetus (B) Betta (C) Clarias (D) Hippocampus\nList II: (1) Magur (2) Sea horse (3) Flying fish (4) Fighting fish","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-2, B-4, C-1, D-3","A-4, B-3, C-2, D-1"],"answer":1,"explanation":"Exocoetus is the flying fish, Betta the fighting fish (aquarium), Clarias the magur (fresh water) and Hippocampus the sea horse (marine).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-72","question":"Match the reptile with its common name.\nList I: (A) Calotes (B) Hemidactylus (C) Chelone (D) Bangarus\nList II: (1) Wall lizard (2) Krait (3) Garden lizard (4) Turtle","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-4, B-1, C-3, D-2"],"answer":2,"explanation":"Calotes is the garden lizard, Hemidactylus the wall lizard, Chelone the turtle and Bangarus the krait (a poisonous snake). Testudo, not Chelone, is the tortoise.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-73","question":"In echinoderms, the mouth and the anus are located respectively on the:","options":["Lower (ventral) side and upper (dorsal) side","Upper (dorsal) side and lower (ventral) side","Lower (ventral) side, both opening together","Anterior end and posterior end"],"answer":0,"explanation":"The digestive system of echinoderms is complete, with the mouth on the lower (ventral) side and the anus on the upper (dorsal) side.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-74","question":"Which statement about Platyhelminthes is INCORRECT?","options":["They are dorso-ventrally flattened, and parasitic forms bear hooks and suckers","Parasitic forms absorb nutrients from the host directly through the body surface","Planaria shows a high capacity for regeneration","The sexes are separate and fertilisation is external"],"answer":3,"explanation":"Flatworms are hermaphrodite (sexes not separate); fertilisation is internal and development passes through many larval stages. The other three statements are correct.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-75","question":"Which statement about Aschelminthes (roundworms) is correct?","options":["They are monoecious, each worm bearing both testes and ovaries","Females are often longer than males","The alimentary canal is incomplete, with a single opening","The body is dorso-ventrally flattened"],"answer":1,"explanation":"Roundworms are dioecious, and the females are often longer than the males. Their alimentary canal is complete with a muscular pharynx, and the body is circular in cross-section.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-76","question":"Which feature is shared by Cnidaria and Ctenophora?","options":["Comb plates used for locomotion in water","Cnidoblasts used for defence and capture of prey","Alternation of polyp and medusa forms in the life cycle","Diploblastic, tissue-level body with radial symmetry"],"answer":3,"explanation":"Both phyla are radially symmetrical, diploblastic and organised at the tissue level. Comb plates are found only in ctenophores, and cnidoblasts and metagenesis only in cnidarians.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-77","question":"Which is a CORRECT difference between Chondrichthyes and Osteichthyes?","options":["The heart is two-chambered in Chondrichthyes but three-chambered in Osteichthyes","Fertilisation is external in Chondrichthyes but internal in Osteichthyes","Gill slits uncovered in Chondrichthyes but covered by an operculum in Osteichthyes","The mouth is terminal in Chondrichthyes but ventral in Osteichthyes"],"answer":2,"explanation":"Cartilaginous fishes lack an operculum; bony fishes have four pairs of gills under an operculum on each side. Both have a two-chambered heart, and the fertilisation and mouth position statements are the wrong way round.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-78","question":"In a male frog, the vasa efferentia (10 to 12 in number) arising from the testes enter the kidneys and open into the:","options":["Cloaca directly","Urinary bladder","Bidder's canal","Oviduct"],"answer":2,"explanation":"The vasa efferentia open into Bidder's canal inside the kidney, which communicates with the urinogenital duct that opens into the cloaca.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-79","question":"A mature female frog can lay about how many ova at a time?","options":["50 to 100","250 to 300","2500 to 3000","25,000 to 30,000"],"answer":2,"explanation":"A mature female frog lays 2500 to 3000 ova at a time. Fertilisation is external in water, and development passes through a tadpole larva.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-80","question":"Which combination of animal and heart structure is CORRECT?","options":["Scoliodon: two-chambered heart","Hyla: four-chambered heart","Crocodilus: three-chambered heart","Columba: three-chambered heart"],"answer":0,"explanation":"Fishes such as Scoliodon (dog fish) have a two-chambered heart. Hyla, an amphibian, has a three-chambered heart, while crocodiles and birds such as Columba have four chambers.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-81","question":"How many of the following statements about class Aves are correct?\n(i) The skin is dry and has no glands except the oil gland at the base of the tail.\n(ii) The heart is three-chambered.\n(iii) The forelimbs are modified into wings, and the hind limbs generally have scales.\n(iv) Fertilisation is external.\n(v) Birds are oviparous and development is direct.","options":["Only two","Only three","Only four","All five"],"answer":1,"explanation":"Statements (i), (iii) and (v) are correct. Birds have a completely four-chambered heart, and fertilisation is internal.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-82","question":"From the following list, how many animals are radially symmetrical as adults?\nAdamsia, Pleurobrachia, Asterias, Taenia, Pheretima, Ophiura, Physalia","options":["Three","Four","Five","Six"],"answer":2,"explanation":"Adamsia and Physalia (cnidarians), Pleurobrachia (ctenophore) and the adult echinoderms Asterias and Ophiura are radially symmetrical. Taenia and Pheretima are bilaterally symmetrical.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-83","question":"Match the cnidarian with its common name.\nList I: (A) Physalia (B) Adamsia (C) Pennatula (D) Gorgonia\nList II: (1) Sea fan (2) Sea anemone (3) Portuguese man-of-war (4) Sea pen","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"Physalia is the Portuguese man-of-war, Adamsia the sea anemone, Pennatula the sea pen and Gorgonia the sea fan. Meandrina is the brain coral.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-84","question":"How many of the following statements about Echinodermata are correct?\n(i) The endoskeleton is made of calcareous ossicles.\n(ii) An excretory system is absent.\n(iii) Fertilisation is usually external and development is indirect, with a free-swimming larva.\n(iv) All echinoderms are marine.\n(v) Ophiura is commonly called the brittle star.","options":["Only two","All five","Only one","Only three"],"answer":1,"explanation":"All five are correct: echinoderms have a calcareous endoskeleton, no excretory system, external fertilisation with indirect development through a free-swimming larva, and are all marine. Ophiura is the brittle star (Cucumaria is the sea cucumber).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-85","question":"How many of the following statements about connective tissues are correct?\n(i) Blood is a specialised connective tissue.\n(ii) In all connective tissues except blood, the cells secrete fibres of collagen or elastin.\n(iii) Adipose tissue is a type of dense connective tissue.\n(iv) Cartilage is present between adjacent bones of the vertebral column.\n(v) Fibroblasts, macrophages and mast cells occur in areolar tissue.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iv) and (v) are correct. Adipose tissue, like areolar tissue, is a loose connective tissue.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-86","question":"How many of the following statements about phylum Mollusca are correct?\n(i) It is the second largest animal phylum.\n(ii) The body is unsegmented, with a distinct head, a muscular foot and a visceral hump.\n(iii) Feather-like gills in the mantle cavity have both respiratory and excretory functions.\n(iv) Molluscs are usually dioecious and oviparous, with indirect development.","options":["Only one","Only three","Only two","All four"],"answer":3,"explanation":"All four are correct. Mollusca is the second largest animal phylum; the body is unsegmented with head, foot and visceral hump; feather-like gills in the mantle cavity serve respiration and excretion; and molluscs are usually dioecious and oviparous with indirect development.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-87","question":"From the following list, how many sites are covered or lined by compound epithelium?\nDry surface of the skin, moist surface of the buccal cavity, pharynx, inner lining of the ducts of salivary glands, inner lining of pancreatic ducts, air sacs of the lungs, lining of the stomach","options":["Three","Four","Six","Five"],"answer":3,"explanation":"The first five sites have compound epithelium, which mainly protects against chemical and mechanical stress. Air sacs are lined by squamous epithelium and the stomach by columnar epithelium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-88","question":"Assertion (A): Hemichordates are placed in phylum Chordata because they have a true notochord.\nReason (R): Hemichordates have a rudimentary structure in the collar region, called the stomochord, that is similar to a notochord.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Hemichordata, once treated as a sub-phylum of Chordata, is now a separate non-chordate phylum; its stomochord is only similar to a notochord. So A is false and R is true.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-89","question":"Match the arthropod with its description.\nList I: (A) Laccifer (B) Locusta (C) Limulus (D) Aedes\nList II: (1) Living fossil (2) Vector of disease (3) Lac insect (4) Gregarious pest","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Laccifer is the lac insect, Locusta a gregarious pest, Limulus (king crab) a living fossil, and Aedes a mosquito vector, like Anopheles and Culex.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-90","question":"Assertion (A): Branchiostoma (amphioxus) is a chordate but not a vertebrate.\nReason (R): In cephalochordates the notochord extends from head to tail and persists throughout life; it is never replaced by a vertebral column.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Vertebrates have a notochord only in the embryo, and it is replaced by a vertebral column in the adult. Because the cephalochordate notochord persists and no vertebral column forms, R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-animal-kingdom-91","question":"An animal is triploblastic and bilaterally symmetrical, its body cavity is not lined by mesoderm, its alimentary canal is complete with a well-developed muscular pharynx, and the sexes are separate with the females often longer than the males. Which animal fits ALL these features?","options":["Fasciola","Ancylostoma","Hirudinaria","Taenia"],"answer":1,"explanation":"A body cavity not lined by mesoderm is a pseudocoelom, the hallmark of Aschelminthes such as Ancylostoma (hookworm), which also have a complete gut with a muscular pharynx and separate sexes. Fasciola and Taenia are acoelomate flatworms, and Hirudinaria is a coelomate, hermaphrodite annelid.","difficulty":"hard","source":"NEET"},
  {"id":"bio-animal-kingdom-92","question":"From the following list, how many animals show metameric segmentation of the body?\nNereis, Pila, Ascaris, Locusta, Octopus, Hirudinaria, Pheretima, Asterias","options":["3","5","4","6"],"answer":2,"explanation":"Annelids (Nereis, Hirudinaria, Pheretima) and arthropods (Locusta) are metamerically segmented. Molluscs such as Pila and Octopus are unsegmented, Ascaris is an unsegmented roundworm and Asterias is an unsegmented echinoderm, so the count is 4.","difficulty":"hard","source":"NEET"},
  {"id":"bio-animal-kingdom-93","question":"How many of the following statements about phylum Cnidaria are correct?\n(i) The single opening of the gastrovascular cavity, the mouth, lies on the hypostome.\n(ii) Digestion is both extracellular and intracellular.\n(iii) Corals have a skeleton made of calcium carbonate.\n(iv) The medusa is the sessile, cylindrical form.\n(v) Cnidoblasts are used for anchorage, defence and the capture of prey.","options":["4","3","5","2"],"answer":0,"explanation":"Only (iv) is wrong: the polyp is the sessile, cylindrical form, while the medusa is umbrella-shaped and free-swimming. The other four statements are standard features of cnidarians.","difficulty":"hard","source":"NEET"},
  {"id":"bio-animal-kingdom-94","question":"Match the animal with its body plan.\nList I: (A) Pleurobrachia (B) Taenia (C) Wuchereria (D) Asterias\nList II: (i) Diploblastic, radially symmetrical (ii) Triploblastic, acoelomate (iii) Triploblastic, pseudocoelomate (iv) Triploblastic coelomate, radial adult but bilateral larva","options":["A-ii, B-i, C-iii, D-iv","A-i, B-iii, C-ii, D-iv","A-i, B-ii, C-iv, D-iii","A-i, B-ii, C-iii, D-iv"],"answer":3,"explanation":"Ctenophores (Pleurobrachia) are diploblastic and radial; flatworms (Taenia) are acoelomate; roundworms (Wuchereria) are pseudocoelomate; echinoderms (Asterias) are coelomate with a radial adult and a bilateral larva.","difficulty":"moderate","source":"NEET"},
  {"id":"bio-animal-kingdom-95","question":"In which pair do BOTH animals have a two-chambered heart (one auricle and one ventricle)?","options":["Salamandra and Hyla","Psittacula and Clarias","Scoliodon and Labeo","Chelone and Crocodilus"],"answer":2,"explanation":"Fishes, both cartilaginous (Scoliodon) and bony (Labeo), have a two-chambered heart. Amphibians and most reptiles (Chelone) have three chambers, while crocodiles and birds such as Psittacula have four; the trap pair mixes a bird with a fish.","difficulty":"hard","source":"NEET"},
  {"id":"bio-animal-kingdom-96","question":"Which statement about the muscle tissues of the human body is INCORRECT?","options":["Skeletal muscle fibres are striated and are bundled together in a parallel fashion","Smooth muscle fibres taper at both ends, show no striations and are involuntary","Cardiac muscle cells are joined by intercalated discs at their fusion points, so the cells contract as a unit","Smooth muscle fibres are joined by intercalated discs and contract only under voluntary control"],"answer":3,"explanation":"Intercalated discs (communication junctions) are a feature of cardiac muscle, and smooth muscle is involuntary; its cells are held together by cell junctions in the walls of organs such as the stomach and blood vessels.","difficulty":"moderate","source":"NEET"},
  {"id":"bio-animal-kingdom-97","question":"From the following, how many are secretions of exocrine glands?\nMucus, saliva, earwax, oil (sebum), milk, digestive enzymes, insulin, thyroxine","options":["6","7","8","4"],"answer":0,"explanation":"Exocrine glands pour their products through ducts: mucus, saliva, earwax, oil, milk and digestive enzymes = 6. Insulin and thyroxine are hormones of ductless glands; counting insulin because the pancreas also has an exocrine part gives 7, and counting every item gives 8.","difficulty":"hard","source":"NEET"},
  {"id":"bio-animal-kingdom-98","question":"How many of the following statements about class Reptilia are correct?\n(i) The body is covered by dry, cornified skin with epidermal scales or scutes.\n(ii) There is no external ear opening; the tympanum represents the ear.\n(iii) Limbs, when present, are two pairs.\n(iv) The heart is usually three-chambered, but four-chambered in crocodiles.\n(v) Snakes and lizards shed their scales as a skin cast.\n(vi) Fertilisation is external and development is indirect.","options":["4","5","3","6"],"answer":1,"explanation":"Statements (i) to (v) are true. Reptiles have internal fertilisation, are oviparous and show direct development, so (vi) is false and the count is 5.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-animal-kingdom-99","question":"Which comparison between chordates and non-chordates is INCORRECTLY stated?","options":["Chordates: heart ventral; non-chordates: heart dorsal (if present)","Chordates: notochord present at least in the embryo; non-chordates: notochord present only in the larva","Chordates: nerve cord dorsal, hollow and single; non-chordates: nerve cord ventral, solid and double (if present)","Chordates: post-anal part (tail) present; non-chordates: post-anal tail absent"],"answer":1,"explanation":"Non-chordates never possess a notochord, at any stage; the larval notochord of urochordates belongs to a chordate subphylum. The other three rows are the standard chordate versus non-chordate differences.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-animal-kingdom-100","question":"Which set of features correctly describes reproduction in Ctenophora?","options":["Sexes not separate; reproduction only by sexual means; external fertilisation; indirect development","Sexes separate; both asexual budding and sexual reproduction; internal fertilisation; direct development","Sexes not separate; reproduction only by sexual means; internal fertilisation; direct development","Sexes separate; reproduction only by sexual means; external fertilisation; indirect development"],"answer":0,"explanation":"Ctenophores (comb jellies) are hermaphrodite, reproduce only sexually, and show external fertilisation with indirect development. Budding and metagenesis are cnidarian traits, which is the usual confusion.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-animal-kingdom-101","question":"Which pair of animals shares BOTH the same type of symmetry as adults AND the same number of embryonic germ layers?","options":["Pleurobrachia and Adamsia","Asterias and Pleurobrachia","Spongilla and Aurelia","Antedon and Pheretima"],"answer":0,"explanation":"Pleurobrachia (ctenophore) and Adamsia (cnidarian) are both radially symmetrical and diploblastic. Asterias is radial as an adult but triploblastic, so pairing it with Pleurobrachia fails on germ layers; Antedon is radial but Pheretima bilateral, and sponges are mostly asymmetrical.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-102","question":"Which option lists a pseudocoelomate, an acoelomate and a coelomate animal, in that order?","options":["Ancylostoma, Pheretima, Fasciola","Wuchereria, Taenia, Pila","Taenia, Ascaris, Nereis","Ascaris, Fasciola, Ancylostoma"],"answer":1,"explanation":"Wuchereria (aschelminth) is pseudocoelomate, Taenia (flatworm) is acoelomate and Pila (mollusc) is coelomate. The other options either break the order or end with a second pseudocoelomate (Ancylostoma).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-103","question":"How many of the following statements about Porifera are correct?\n(i) Choanocytes (collar cells) line the spongocoel and the canals.\n(ii) Digestion is intracellular.\n(iii) The sexes are separate and fertilisation is external.\n(iv) Water leaves the body through the osculum.\n(v) Development is indirect, with a larval stage morphologically distinct from the adult.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iv) and (v) are correct. Sponges are hermaphrodite (sexes not separate) and fertilisation is internal, so (iii) is wrong on both counts.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-104","question":"Which feature is present in Cnidaria but ABSENT in Ctenophora?","options":["A diploblastic body with tissue level of organisation","Digestion that is both extracellular and intracellular in nature","Radial symmetry with an exclusively aquatic habit","Cnidoblasts used for anchorage, defence and prey capture"],"answer":3,"explanation":"Cnidoblasts are the defining feature of Cnidaria. Ctenophores are also diploblastic, radially symmetrical, aquatic (exclusively marine) and digest food both extracellularly and intracellularly.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-105","question":"Assertion (A): Echinoderms have no specialised excretory system.\nReason (R): In echinoderms, excretion is carried out by flame cells.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"NCERT states that an excretory system is absent in echinoderms. Flame cells are the excretory structures of Platyhelminthes, so R is false.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-106","question":"Match the animal with its common name.\nList I: (A) Echinus (B) Cucumaria (C) Ophiura (D) Chaetopleura\nList II: (1) Brittle star (2) Chiton (3) Sea urchin (4) Sea cucumber","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"answer":1,"explanation":"Echinus is the sea urchin, Cucumaria the sea cucumber, Ophiura the brittle star and Chaetopleura the chiton (a mollusc, not an echinoderm).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-107","question":"From the following list, how many animals are oviparous?\nOrnithorhynchus, Pteropus, Struthio, Chelone, Macropus, Rana, Delphinus, Columba","options":["Four","Five","Six","Seven"],"answer":1,"explanation":"Ornithorhynchus (egg-laying mammal), Struthio, Chelone, Rana and Columba are oviparous: five. Pteropus, Macropus and Delphinus are viviparous mammals.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-108","question":"Which combination of animal and excretory structure is CORRECT?","options":["Ascaris – nephridia","Balanoglossus – Malpighian tubules","Asterias – proboscis gland","Fasciola – flame cells"],"answer":3,"explanation":"Flame cells are the excretory cells of flatworms such as Fasciola. Nephridia belong to annelids, Malpighian tubules to arthropods, and the proboscis gland to Balanoglossus; Asterias has no excretory system.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-109","question":"In chordates, the origin of the notochord, the nature of the nerve cord and the position of the heart are respectively:","options":["Mesodermal; dorsal, hollow and single; ventral","Endodermal; dorsal, hollow and single; ventral","Mesodermal; ventral, solid and double; dorsal","Ectodermal; dorsal, solid and single; dorsal"],"answer":0,"explanation":"The notochord is a mesodermally derived rod; chordates have a single dorsal hollow nerve cord and a ventral heart. A ventral solid double nerve cord with a dorsal heart is the non-chordate pattern.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-110","question":"Which pair names a freshwater sponge followed by the bath sponge?","options":["Sycon and Spongilla","Euspongia and Spongilla","Spongilla and Euspongia","Scypha and Euspongia"],"answer":2,"explanation":"Spongilla is the freshwater sponge and Euspongia the bath sponge, so the order matters: 'Euspongia and Spongilla' names the right pair the wrong way round. Sycon (also called Scypha) is a marine sponge.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-animal-kingdom-111","question":"According to NCERT, some parasitic flatworms such as Taenia obtain their nutrition by:","options":["Digesting host tissue with enzymes released from their flame cells","Sucking host blood through a muscular pharynx and a rasping radula","Depending on symbiotic algae that live in their gastric cavity","Absorbing nutrients from the host directly through the body surface"],"answer":3,"explanation":"Parasitic flatworms have hooks and suckers, and some absorb nutrients from the host directly through their body surface. Flame cells are excretory, and the radula is a molluscan feeding organ.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-animal-kingdom-112","question":"How many of the following statements about phylum Annelida are correct?\n(i) Nereis possesses lateral appendages, parapodia, that help in swimming.\n(ii) The circulatory system is of the open type.\n(iii) The neural system has paired ganglia connected by lateral nerves to a double ventral nerve cord.\n(iv) Earthworms and leeches are monoecious, whereas Nereis is dioecious.\n(v) Nephridia help in osmoregulation and excretion.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Annelids have a closed circulatory system, so (ii) is wrong; the other four statements are correct as given in NCERT.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-113","question":"Which statement about class Amphibia is INCORRECT?","options":["Fertilisation is internal and development is direct","The skin is moist and has no scales","The alimentary canal, urinary and reproductive tracts open into a common cloaca","The heart has two auricles and one ventricle"],"answer":0,"explanation":"Amphibians show external fertilisation and indirect development (through a larval stage). Internal fertilisation with direct development is the reptilian pattern.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-114","question":"Match the animal with its class.\nList I: (A) Pteropus (B) Aptenodytes (C) Ichthyophis (D) Hippocampus\nList II: (1) Osteichthyes (2) Amphibia (3) Aves (4) Mammalia","options":["A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Pteropus (flying fox) is a mammal, Aptenodytes (penguin) a bird, Ichthyophis a limbless amphibian and Hippocampus (sea horse) a bony fish. Each name tempts a wrong class: a flying mammal, a flightless bird, a snake-like amphibian and a horse-named fish.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-115","question":"Which pair consists of two FRESHWATER bony fishes?","options":["Exocoetus and Catla","Labeo and Clarias","Hippocampus and Betta","Pristis and Labeo"],"answer":1,"explanation":"Labeo (rohu) and Clarias (magur) are freshwater bony fishes. Exocoetus and Hippocampus are marine, Betta is an aquarium fish, and Pristis (saw fish) is cartilaginous.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-116","question":"Which set of features is shared by ALL members of Echinodermata, Hemichordata and Chordata?","options":["Bilateral symmetry in the adult, a true coelom and a closed circulatory system","Gill slits, a dorsal nerve cord and an open circulatory system","A triploblastic body, a true coelom and organ-system level of organisation","A triploblastic body, a true coelom and external fertilisation in every member"],"answer":2,"explanation":"All three phyla are triploblastic coelomates with organ-system organisation. Adult echinoderms are radial, hemichordates have an open circulation while chordates have a closed one, and many chordates show internal fertilisation.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-117","question":"Which statement about Balanoglossus is correct?","options":["A rudimentary stomochord in the collar region resembles a notochord","Its circulatory system is closed, with a ventral muscular heart and arteries","It is hermaphrodite and shows internal fertilisation","It excretes through a pair of nephridia in each body segment"],"answer":0,"explanation":"Hemichordates have a stomochord, a rudimentary structure in the collar region similar to a notochord. Their circulation is open, sexes are separate, fertilisation is external and excretion is by the proboscis gland.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-118","question":"From the following list, how many animals have a CLOSED circulatory system?\nPheretima, Periplaneta, Balanoglossus, Petromyzon, Nereis, Pila, Labeo","options":["Three","Four","Five","Six"],"answer":1,"explanation":"Annelids (Pheretima, Nereis) and chordates (Petromyzon, Labeo) have closed circulation: four. Periplaneta, Pila and Balanoglossus (a hemichordate) have an open system.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-119","question":"Which cell junctions, if missing from an epithelium, would allow substances to leak across the tissue between the cells?","options":["Adhering junctions","Gap junctions","Intercalated discs","Tight junctions"],"answer":3,"explanation":"Tight junctions stop substances from leaking across a tissue. Adhering junctions cement cells together and gap junctions connect the cytoplasm of adjoining cells.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-animal-kingdom-120","question":"Muscle fibres that taper at both ends, show no striations, are held together by cell junctions and are bundled in a connective tissue sheath are found in the:","options":["Biceps attached to the bones of the arm","Walls of the stomach and intestine","Wall of the heart","Tongue and the diaphragm"],"answer":1,"explanation":"These are smooth (fusiform, non-striated, involuntary) muscle fibres of the walls of internal organs such as the stomach, intestine and blood vessels. Biceps, tongue and diaphragm are skeletal; the heart wall is cardiac muscle.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-121","question":"During aestivation and hibernation, the frog carries out gaseous exchange through its:","options":["Skin","Lungs","Buccal cavity and lungs","Gills and skin"],"answer":0,"explanation":"During aestivation and hibernation gaseous exchange takes place only through the skin (cutaneous respiration). On land, the buccal cavity, skin and lungs are all used.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-122","question":"In the frog brain, the optic lobes, the olfactory lobes and the medulla oblongata belong respectively to the:","options":["Forebrain, midbrain and hindbrain","Midbrain, hindbrain and forebrain","Forebrain, forebrain and hindbrain","Midbrain, forebrain and hindbrain"],"answer":3,"explanation":"The forebrain includes the olfactory lobes, cerebral hemispheres and diencephalon; the midbrain bears the pair of optic lobes; the hindbrain has the cerebellum and medulla oblongata.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-123","question":"How many pairs of cranial nerves arise from the brain of a frog?","options":["Twelve pairs","Eight pairs","Ten pairs","Thirty-one pairs"],"answer":2,"explanation":"The frog has ten pairs of cranial nerves. Twelve pairs is the human (amniote) number, and 31 pairs is the number of human spinal nerves.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-animal-kingdom-124","question":"How many of the following statements about the frog are correct?\n(i) The sinus venosus joins the right atrium.\n(ii) The ventricle opens into a sac-like conus arteriosus on the ventral side of the heart.\n(iii) Its red blood cells are enucleate, like those of humans.\n(iv) It has a hepatic portal system but no renal portal system.\n(v) In females, the ureters and oviducts open separately into the cloaca.","options":["Two","Three","Four","Five"],"answer":1,"explanation":"Statements (i), (ii) and (v) are correct. Frog RBCs are nucleated, and the frog has both hepatic portal and renal portal systems.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-125","question":"Which sense organs of the frog are well organised structures, the others being only cellular aggregations around nerve endings?","options":["Eyes and internal ears","Sensory papillae and taste buds","Nasal epithelium and eyes","Tympanum and taste buds"],"answer":0,"explanation":"NCERT notes that of the frog's sense organs (touch, taste, smell, vision, hearing), only the eyes and internal ears are well-organised structures.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-126","question":"Assertion (A): A frog never drinks water.\nReason (R): A frog absorbs water through its skin.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The frog's moist skin absorbs water, which is why it does not need to drink, so R correctly explains A.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-127","question":"Which of the following does NOT belong to subphylum Vertebrata?","options":["Myxine","Salpa","Petromyzon","Ichthyophis"],"answer":1,"explanation":"Salpa is a urochordate, a protochordate whose notochord is confined to the larval tail. Myxine and Petromyzon are jawless vertebrates (cyclostomes) and Ichthyophis is an amphibian.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-128","question":"A vertebrate lives as an ectoparasite on fishes, has 6–15 pairs of gill slits, a circular sucking mouth without jaws and no paired fins. After it migrates to fresh water and spawns, it:","options":["Returns to the ocean and spawns again in the following season","Guards the eggs until they hatch into miniature adults in the stream","Remains in fresh water and lives on as a free-living adult","Dies within days; its larvae return to the ocean after metamorphosis"],"answer":3,"explanation":"This is a cyclostome. Cyclostomes are marine but migrate to fresh water to spawn, die within a few days of spawning, and their larvae return to the ocean after metamorphosis.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-129","question":"Which of the following animals is viviparous AND capable of true flight?","options":["Columba","Ornithorhynchus","Pteropus","Struthio"],"answer":2,"explanation":"Pteropus (flying fox) is a viviparous mammal that flies. Columba flies but lays eggs; Ornithorhynchus lays eggs and Struthio (ostrich) is flightless and oviparous.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-130","question":"In diploblastic animals, the undifferentiated layer present between the ectoderm and the endoderm is the:","options":["Mesoderm","Mesoglea","Mesentery","Mesenchyme"],"answer":1,"explanation":"Diploblastic animals such as cnidarians have an undifferentiated mesoglea between the outer ectoderm and inner endoderm. A true mesoderm is the third germ layer of triploblastic animals.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-animal-kingdom-131","question":"From the following list, how many animals belong to phylum Arthropoda?\nApis, Bombyx, Laccifer, Culex, Aedes, Locusta, Limulus, Pila, Dentalium, Ophiura","options":["Five","Six","Seven","Eight"],"answer":2,"explanation":"Apis, Bombyx, Laccifer, Culex, Aedes, Locusta and Limulus (king crab, a living fossil) are arthropods: seven. Pila and Dentalium are molluscs, and Ophiura (brittle star) is an echinoderm.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-132","question":"Superclass Tetrapoda of division Gnathostomata includes the classes:","options":["Chondrichthyes, Osteichthyes, Amphibia and Reptilia","Cyclostomata, Amphibia, Reptilia and Aves","Reptilia, Aves and Mammalia only","Amphibia, Reptilia, Aves and Mammalia"],"answer":3,"explanation":"Gnathostomata has two superclasses: Pisces (Chondrichthyes, Osteichthyes) and Tetrapoda (Amphibia, Reptilia, Aves, Mammalia). Cyclostomata belong to Agnatha, not Gnathostomata.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-133","question":"Which pair consists of animals that BOTH have an incomplete digestive system with a single opening?","options":["Fasciola and Hydra","Ascaris and Taenia","Pheretima and Aurelia","Ancylostoma and Fasciola"],"answer":0,"explanation":"Flatworms (Fasciola) and cnidarians (Hydra) have a single opening serving as both mouth and anus. Aschelminthes (Ascaris, Ancylostoma) and annelids (Pheretima) have a complete alimentary canal.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-animal-kingdom-134","question":"Simple squamous epithelium, made of a single thin layer of flattened cells with irregular boundaries, is found in the:","options":["Lining of the stomach and intestine","Bronchioles and fallopian tubes","Dry surface of the skin and the lining of the buccal cavity","Walls of blood vessels and air sacs of the lungs"],"answer":3,"explanation":"Squamous epithelium lines blood vessels and lung air sacs where diffusion occurs. Columnar epithelium lines the stomach and intestine, ciliated epithelium the bronchioles and fallopian tubes, and the skin surface is compound epithelium.","difficulty":"moderate","source":"NEET UG"},
];

export default questions;
